function beginReward(kind){
 if(rewardSession)return;
 if(rewardProviderMode(window.location.hostname)!=='local-demo'){toast('실제 광고 서비스가 아직 연결되지 않았습니다.');return;}
 const status=rewardStatus(state,kind);if(!status.ok){toast(status.msg);showRewards();return;}
 const r=REWARDS[kind];rewardSession=createDemoSession({id:crypto.randomUUID(),kind,day:rewardDay()});
 openDialog('reward-preview',`<span class="eyebrow">TEST PREVIEW · 실제 광고 아님</span><h2>${r.name} 보상 체험</h2><p>체험을 완료하면 <b>${r.label}</b>를 게임 안에서 받습니다. 중간에 닫으면 보상은 지급되지 않으며 플레이에는 불이익이 없습니다.</p><div class="reward-preview-art"><span>${r.icon}</span><b>아이디어를 키우는 작은 기회</b><small>외부 광고나 광고 수익이 없는 개발용 미리보기</small></div><div class="reward-progress"><i id="reward-progress-fill"></i></div><p id="reward-countdown" class="reward-countdown" role="status">5초 남음</p><button data-action="close" class="full">건너뛰고 게임으로 돌아가기</button><p class="help">화면을 보고 있는 동안만 체험이 진행됩니다. 게임 시간은 잠시 멈춥니다.</p>`);
}
function advanceReward(dt){
 if(!rewardSession||modal!=='reward-preview')return;
 rewardSession.advance(dt*1000,!document.hidden);
 const remaining=rewardSession.remaining;
 $('#reward-progress-fill').style.width=((5000-remaining)/50)+'%';
 const label=Math.ceil(remaining/1000)+'초 남음';if($('#reward-countdown').textContent!==label)$('#reward-countdown').textContent=label;
 const receipt=rewardSession.complete();if(!receipt)return;rewardSession=null;
 const result=grantReward(state,receipt);changed();
 if(!result.ok){toast(result.msg);showRewards();return;}
 audio.play('win');renderer.burst(analysis.owned[0]?.i??-1,REWARDS[receipt.kind].label+' 획득');
 openDialog('reward-result',`<div class="rush-result"><span>${REWARDS[receipt.kind].icon}</span><p>테스트 보상 지급 완료</p><h2>${REWARDS[receipt.kind].label}</h2><p>${REWARDS[receipt.kind].description}</p><button data-action="close" class="primary full">게임에서 사용하기 →</button><button data-action="rewards" class="full">보관함 보기</button><p class="help">게임 전용 보상이며 현금화·양도할 수 없습니다.</p></div>`);
}
